// Simple Asteroid Miner game targeting <canvas id="game">
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  const ship = { x: width / 2, y: height / 2, r: 15, speed: 3, vx: 0, vy: 0 };
  const keys = { ArrowUp: false, ArrowDown: false, ArrowLeft: false, ArrowRight: false };

  const ores = [];
  const asteroids = [];
  let score = 0;
  let gameOver = false;

  function rand(min, max) { return Math.random() * (max - min) + min; }

  function spawnOre() {
    ores.push({ x: rand(0, width), y: rand(0, height), r: 8, collected: false });
  }

  function spawnAsteroid() {
    const angle = rand(0, Math.PI * 2);
    const speed = rand(1, 2.5);
    asteroids.push({
      x: rand(0, width),
      y: rand(0, height),
      r: rand(20, 35),
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
    });
  }

  // initial spawns
  for (let i = 0; i < 5; i++) spawnOre();
  for (let i = 0; i < 3; i++) spawnAsteroid();

  function update() {
    if (gameOver) return;
    // ship movement
    ship.vx = (keys.ArrowRight - keys.ArrowLeft) * ship.speed;
    ship.vy = (keys.ArrowDown - keys.ArrowUp) * ship.speed;
    ship.x = (ship.x + ship.vx + width) % width;
    ship.y = (ship.y + ship.vy + height) % height;

    // update asteroids
    for (const a of asteroids) {
      a.x = (a.x + a.vx + width) % width;
      a.y = (a.y + a.vy + height) % height;
    }

    // check collisions with ore
    for (const o of ores) {
      if (!o.collected && dist(ship, o) < ship.r + o.r) {
        o.collected = true;
        score++;
        // replace ore
        spawnOre();
      }
    }

    // check collisions with asteroids
    for (const a of asteroids) {
      if (dist(ship, a) < ship.r + a.r) {
        gameOver = true;
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.fillStyle = '#0f0';
    ctx.beginPath();
    ctx.arc(ship.x, ship.y, ship.r, 0, Math.PI * 2);
    ctx.fill();
    // ores
    ctx.fillStyle = '#ff0';
    for (const o of ores) if (!o.collected) {
      ctx.beginPath();
      ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // asteroids
    ctx.fillStyle = '#f00';
    for (const a of asteroids) {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    }
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    // game over
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '48px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  function dist(a, b) { return Math.hypot(a.x - b.x, a.y - b.y); }

  // input handling
  window.addEventListener('keydown', e => { if (e.key in keys) keys[e.key] = true; });
  window.addEventListener('keyup', e => { if (e.key in keys) keys[e.key] = false; });

  // start
  requestAnimationFrame(loop);
})();
